INSERT INTO passages (report, section, paragraph_id, page, body) VALUES
('jack-smith-vol1', 'Section 4: Filing and an Adjournment of the CIPA Section 5 Deadline', 'court-opinion-order-defendant-s', '140', 'Court Opinion & Order (Defendant''s Motion for Pretrial Rule 17(c)165 See also, e.g., United States v. Correia, 55 F.4th 12, 26 (1st Cir. 2022); Knickerbocker Merchandising Co. v. United States, 13 F.2d 544, 546 (2d Cir. 1926); United States v. Coyle, 63 F.3d 1239, 1243 (3d Cir. 1995); United States v. Hester, 880 F.2d 799, 803 (4th Cir. 1989); United States v. Dillman, 15 F.3d 384, 392-393 (5th Cir. 1994); United States v. Kennedy, 714 F.3d 951,958 (6th Cir. 2013); United States v. Schwartz, 787 F.2d 257,265 (7th Cir. 1986); United States v. Marley, 549 F.2d 561, 563-564 (8th Cir. 1977) ("It must also be noted that the courts have long recognized that scienter may be established where reckless disregard of truth or falsity is present."); United States v. Dearing, 504 F.3d 897,903 (9th Cir. 2007); United States v. Cochran, 109 F.3d 660,665 (10th Cir. 1997); United States v. Clay, 832 F.3d 1259, 1311 (I Ith Cir. 2016).Show full note 11/27/2023'),
('jack-smith-vol1', 'Section 4: Filing and an Adjournment of the CIPA Section 5 Deadline', '171-172-12-1-2023', '140', '171,172 12/1/2023 Dismiss Based on Presidential Immunity and Constitutional'),
